#!/usr/bin/env python3
"""Test of regc's `evolve_friend` (contract 65): species.toml `evolve_friend = [level, "target"]` becomes reg.bin evo_level = level | 0x80 (EVO_FRIEND: the level floor in the low 7 bits + the friendship mark), evo_to = the
target, NO evostone.bin record; it is exclusive with `evolve`, `evolve_stone` and `evolve_trade`, the level must be 2..100, the target an existing other species; the real data uses it for exactly hatchkip -> shellbrute (28)
and dashkip -> dashmark (31); the generated header defines EVO_FRIEND 128; the Registro stays completable (species_sources_check counts the evolution). Runs regc.parse() on the real data with one species patched in memory.
  python3 -I tools/regc_friend_test.py        (exit status 1 on a failure; part of tools/build_assets.sh)"""
import copy
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "tools"))
import regc  # noqa: E402

fails = 0


def check(what, cond):
    global fails
    print(("ok   " if cond else "FAIL ") + what)
    if not cond:
        fails += 1


REAL = regc.load_toml
SPECIES = REAL("species.toml")
NAMES = list(SPECIES)
SID = {n: i + 1 for i, n in enumerate(NAMES)}


def patched(edit):
    sp = copy.deepcopy(SPECIES)
    edit(sp)
    regc.load_toml = lambda n: sp if n == "species.toml" else REAL(n)
    try:
        return regc.parse(), ""
    except regc.RegError as e:
        return None, str(e)
    finally:
        regc.load_toml = REAL


base, err = patched(lambda s: None)
check(f"the real data parses ({err})", base is not None)
friend = {
    n: SPECIES[n]["evolve_friend"] for n in NAMES if "evolve_friend" in SPECIES[n]
}
check(
    "exactly two lines use it: hatchkip -> shellbrute at 28, dashkip -> dashmark at 31",
    friend == {"hatchkip": [28, "shellbrute"], "dashkip": [31, "dashmark"]},
)
for n, (lv, tgt) in friend.items():
    s = base["species"][SID[n] - 1]
    check(
        f"{n}: reg.bin evo_level = {lv} | 0x80 = {lv | 0x80}, evo_to = {tgt}",
        s["ev_lv"] == (lv | regc.EVO_FRIEND) and s["ev_to"] == SID[tgt],
    )
    rec = regc.emit_reg(base)
    off = 12 + 40 * SID[n]
    check(
        f"{n}: the bytes of reg.bin say the same (record bytes 10 / 11 = {lv | 0x80} / {SID[tgt]})",
        rec[off + 10] == (lv | 0x80) and rec[off + 11] == SID[tgt],
    )
    check(
        f"{n}: no evostone.bin record (the plain by-level readers see a level evolution at {lv})",
        all(
            r[0] != SID[n]
            for r in [
                regc.emit_evostone(base)[12 + 4 * i : 16 + 4 * i]
                for i in range((len(regc.emit_evostone(base)) - 12) // 4)
            ]
        ),
    )
bit7 = [n for i, n in enumerate(NAMES) if base["species"][i]["ev_lv"] & 0x80]
check("no other species has bit 7 set in evo_level", sorted(bit7) == sorted(friend))
check(
    "every plain `evolve` level is 1..100 (bit 7 never collides with a real level)",
    all(1 <= SPECIES[n]["evolve"][0] <= 100 for n in NAMES if "evolve" in SPECIES[n]),
)
h = (ROOT / "nucleo" / "gen" / "reg_gen.h").read_text()
check(
    "nucleo/gen/reg_gen.h defines EVO_FRIEND 128 (generated by regc.py)",
    "#define EVO_FRIEND 128" in h,
)

# a species with no evolution of its own: give it one
free = [
    n
    for n in NAMES
    if not any(
        k in SPECIES[n]
        for k in ("evolve", "evolve_stone", "evolve_trade", "evolve_friend")
    )
][0]
target = [n for n in NAMES if n != free][3]


def add(sp):
    sp[free]["evolve_friend"] = [40, target]


d, err = patched(add)
check(f'evolve_friend = [40, "{target}"] on {free} parses ({err})', d is not None)
if d is not None:
    s = d["species"][SID[free] - 1]
    check(
        f"{free}: evo_level = 40 | 0x80, evo_to = {target}",
        s["ev_lv"] == 40 | 0x80 and s["ev_to"] == SID[target],
    )

lvl = [n for n in NAMES if "evolve" in SPECIES[n]][0]
stn = [n for n in NAMES if "evolve_stone" in SPECIES[n]][0]
trd = [n for n in NAMES if "evolve_trade" in SPECIES[n]][0]
for what, who in (("evolve", lvl), ("evolve_stone", stn), ("evolve_trade", trd)):
    d, err = patched(
        lambda sp, who=who: sp[who].__setitem__(
            "evolve_friend", [30, target if target != who else NAMES[1]]
        )
    )
    check(
        f"evolve_friend + {what} is refused: {err[:80]}",
        d is None and "exclusive" in err,
    )
for what, val, word in (
    ("a level below 2", [1, target], "evolve_friend must be"),
    ("a level above 100", [101, target], "evolve_friend must be"),
    ("a string", "shellbrute", "evolve_friend must be"),
    ("a one-element list", [30], "evolve_friend must be"),
    ("an unknown target", [30, "no_such_species"], "unknown"),
    ("its own species", [30, free], "own target"),
    ("a non-string target", [30, 7], "evolve_friend must be"),
):
    d, err = patched(lambda sp, val=val: sp[free].__setitem__("evolve_friend", val))
    check(f"{what} is refused: {err[:80]}", d is None and word in err)

# the Registro stays completable: species_sources_check follows evolve_friend
r = subprocess.run(
    [sys.executable, "-I", str(ROOT / "tools" / "species_sources_check.py")],
    capture_output=True,
    text=True,
)
check(
    f"species_sources_check: every species has a source ({r.stdout.strip().splitlines()[-1] if r.stdout.strip() else r.stderr.strip()[:80]})",
    r.returncode == 0,
)
src = (ROOT / "tools" / "species_sources_check.py").read_text()
check(
    "species_sources_check.py counts the friendship evolution as a source (hatchkip -> shellbrute, dashkip -> dashmark have no other)",
    '"evolve_friend"' in src,
)
print(f"regc_friend_test: {'FAILED ' + str(fails) if fails else 'all ok'}")
sys.exit(1 if fails else 0)
